/**
 * useTables Hook Tests
 *
 * Tests for the custom useTables hook that manages restaurant table CRUD operations.
 * This file tests fetching tables, creating tables, updating tables, deleting tables,
 * and updating table status.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { renderHook, waitFor, act } from '@testing-library/react'
import { useTables } from '@/hooks/useTables'
import { createMockRestaurantTable } from '@/__tests__/fixtures/test-data'
import { createMockSupabaseClient } from '@/__tests__/mocks/supabase'

// Mock the Supabase client
vi.mock('@/lib/supabase/client', () => ({
  createClient: vi.fn(),
}))

// Import after mocking to get the mocked version
import { createClient } from '@/lib/supabase/client'

describe('useTables Hook', () => {
  const mockOrganizationId = 'test-org-id'

  beforeEach(() => {
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  describe('Initial State', () => {
    it('should initialize with empty tables array', () => {
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const { result } = renderHook(() => useTables(mockOrganizationId))

      expect(result.current.tables).toEqual([])
      expect(result.current.isLoading).toBe(false)
      expect(result.current.error).toBeNull()
    })

    it('should provide all CRUD methods', () => {
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const { result } = renderHook(() => useTables(mockOrganizationId))

      expect(typeof result.current.fetchTables).toBe('function')
      expect(typeof result.current.createTable).toBe('function')
      expect(typeof result.current.updateTable).toBe('function')
      expect(typeof result.current.deleteTable).toBe('function')
      expect(typeof result.current.updateStatus).toBe('function')
    })
  })

  describe('fetchTables', () => {
    it('should fetch tables successfully', async () => {
      // Arrange
      const mockTables = [
        createMockRestaurantTable({
          id: 'table-1',
          table_number: 'Masa 1',
          organization_id: mockOrganizationId,
          current_status: 'empty',
        }),
        createMockRestaurantTable({
          id: 'table-2',
          table_number: 'Masa 2',
          organization_id: mockOrganizationId,
          current_status: 'occupied',
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createTablesQueryBuilder(mockTables)
      })

      mockClient.from = fromMock as any

      function createTablesQueryBuilder(data: any[]) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.fetchTables()
      })

      // Assert
      await waitFor(() => {
        expect(result.current.tables).toHaveLength(2)
      })

      expect(result.current.tables[0].table_number).toBe('Masa 1')
      expect(result.current.tables[0].current_status).toBe('empty')
      expect(result.current.tables[1].table_number).toBe('Masa 2')
      expect(result.current.tables[1].current_status).toBe('occupied')
      expect(result.current.isLoading).toBe(false)
      expect(result.current.error).toBeNull()
    })

    it('should handle fetch error gracefully', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createErrorQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createErrorQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.fetchTables()
      })

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe('Failed to fetch tables')
      })

      expect(result.current.tables).toEqual([])
      expect(result.current.isLoading).toBe(false)
    })

    it('should not fetch when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn()
      mockClient.from = fromMock as any

      // Act
      const { result } = renderHook(() => useTables(undefined))

      await act(async () => {
        await result.current.fetchTables()
      })

      // Assert
      expect(fromMock).not.toHaveBeenCalled()
      expect(result.current.tables).toEqual([])
    })

    it('should set loading state during fetch', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let resolvePromise: (value: any) => void
      const delayedPromise = new Promise((resolve) => {
        resolvePromise = resolve
      })

      const fromMock = vi.fn(() => {
        return createDelayedQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createDelayedQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return delayedPromise.then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      let fetchPromise: Promise<void>
      act(() => {
        fetchPromise = result.current.fetchTables()
      })

      // Assert - loading should be true
      await waitFor(() => {
        expect(result.current.isLoading).toBe(true)
      })

      // Resolve the promise
      act(() => {
        resolvePromise!({ data: [], error: null })
      })

      await act(async () => {
        await fetchPromise!
      })

      // Assert - loading should be false
      await waitFor(() => {
        expect(result.current.isLoading).toBe(false)
      })
    })

    it('should order tables by table_number', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let capturedOrderColumn: string | undefined
      let capturedOrderOptions: any

      const fromMock = vi.fn(() => {
        return createOrderCheckingQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createOrderCheckingQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn((column: string, options: any) => {
            capturedOrderColumn = column
            capturedOrderOptions = options
            return queryBuilder
          }),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: [],
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.fetchTables()
      })

      // Assert
      expect(capturedOrderColumn).toBe('table_number')
      expect(capturedOrderOptions).toEqual({ ascending: true })
    })
  })

  describe('createTable', () => {
    it('should create a new table successfully', async () => {
      // Arrange
      const newTableId = 'new-table-123'

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createTableInsertQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn(() => queryBuilder),
          select: vi.fn(() => queryBuilder),
          single: vi.fn(() => {
            return Promise.resolve({
              data: { id: newTableId, table_number: 'Masa 10' },
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      let tableId: string = ''
      await act(async () => {
        tableId = await result.current.createTable({
          table_number: 'Masa 10',
        })
      })

      // Assert
      expect(tableId).toBe(newTableId)
    })

    it('should create table with trimmed name', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let capturedData: any = null

      const fromMock = vi.fn(() => {
        return createTableInsertQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn((data) => {
            capturedData = data
            return queryBuilder
          }),
          select: vi.fn(() => queryBuilder),
          single: vi.fn(() => {
            return Promise.resolve({
              data: { id: 'new-table-123' },
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.createTable({
          table_number: '  Masa 5  ',
        })
      })

      // Assert
      expect(capturedData.table_number).toBe('Masa 5')
    })

    it('should create table with default empty status', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let capturedData: any = null

      const fromMock = vi.fn(() => {
        return createTableInsertQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn((data) => {
            capturedData = data
            return queryBuilder
          }),
          select: vi.fn(() => queryBuilder),
          single: vi.fn(() => {
            return Promise.resolve({
              data: { id: 'new-table-123' },
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.createTable({
          table_number: 'Masa 1',
        })
      })

      // Assert
      expect(capturedData.current_status).toBe('empty')
      expect(capturedData.organization_id).toBe(mockOrganizationId)
    })

    it('should create table with custom status', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let capturedData: any = null

      const fromMock = vi.fn(() => {
        return createTableInsertQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn((data) => {
            capturedData = data
            return queryBuilder
          }),
          select: vi.fn(() => queryBuilder),
          single: vi.fn(() => {
            return Promise.resolve({
              data: { id: 'new-table-123' },
              error: null,
            })
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.createTable({
          table_number: 'Masa 1',
          current_status: 'occupied',
        })
      })

      // Assert
      expect(capturedData.current_status).toBe('occupied')
    })

    it('should throw error when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      // Act
      const { result } = renderHook(() => useTables(undefined))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.createTable({
            table_number: 'Masa 1',
          })
        })
      }).rejects.toThrow('Organization ID is required')
    })

    it('should handle database error during creation', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createTableInsertQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableInsertQueryBuilder() {
        const queryBuilder = {
          insert: vi.fn(() => queryBuilder),
          select: vi.fn(() => queryBuilder),
          single: vi.fn(() => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            })
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.createTable({
            table_number: 'Masa 1',
          })
        })
      }).rejects.toThrow()
    })
  })

  describe('updateTable', () => {
    it('should update table successfully', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createTableUpdateQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableUpdateQueryBuilder() {
        const queryBuilder = {
          update: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.updateTable('table-123', {
          table_number: 'Updated Masa',
        })
      })

      // Assert - should not throw
      expect(true).toBe(true)
    })

    it('should update table with trimmed name', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let capturedData: any = null

      const fromMock = vi.fn(() => {
        return createTableUpdateQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableUpdateQueryBuilder() {
        const queryBuilder = {
          update: vi.fn((data) => {
            capturedData = data
            return queryBuilder
          }),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.updateTable('table-123', {
          table_number: '  Masa VIP  ',
        })
      })

      // Assert
      expect(capturedData.table_number).toBe('Masa VIP')
    })

    it('should throw error when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      // Act
      const { result } = renderHook(() => useTables(undefined))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.updateTable('table-123', {
            table_number: 'Updated Masa',
          })
        })
      }).rejects.toThrow('Organization ID is required')
    })

    it('should handle database error during update', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createTableUpdateQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableUpdateQueryBuilder() {
        const queryBuilder = {
          update: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.updateTable('table-123', {
            table_number: 'Updated Masa',
          })
        })
      }).rejects.toThrow()
    })
  })

  describe('deleteTable', () => {
    it('should delete table successfully', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createTableDeleteQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableDeleteQueryBuilder() {
        const queryBuilder = {
          delete: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.deleteTable('table-123')
      })

      // Assert - should not throw
      expect(true).toBe(true)
    })

    it('should throw error when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      // Act
      const { result } = renderHook(() => useTables(undefined))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.deleteTable('table-123')
        })
      }).rejects.toThrow('Organization ID is required')
    })

    it('should handle database error during deletion', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createTableDeleteQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createTableDeleteQueryBuilder() {
        const queryBuilder = {
          delete: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.deleteTable('table-123')
        })
      }).rejects.toThrow()
    })
  })

  describe('updateStatus', () => {
    it('should update table status successfully', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let capturedStatus: string | undefined

      const fromMock = vi.fn(() => {
        return createStatusUpdateQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createStatusUpdateQueryBuilder() {
        const queryBuilder = {
          update: vi.fn((data: any) => {
            capturedStatus = data.current_status
            return queryBuilder
          }),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.updateStatus('table-123', 'occupied')
      })

      // Assert
      expect(capturedStatus).toBe('occupied')
    })

    it('should update status to service_needed', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      let capturedStatus: string | undefined

      const fromMock = vi.fn(() => {
        return createStatusUpdateQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createStatusUpdateQueryBuilder() {
        const queryBuilder = {
          update: vi.fn((data: any) => {
            capturedStatus = data.current_status
            return queryBuilder
          }),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      await act(async () => {
        await result.current.updateStatus('table-123', 'service_needed')
      })

      // Assert
      expect(capturedStatus).toBe('service_needed')
    })

    it('should throw error when organizationId is undefined', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      // Act
      const { result } = renderHook(() => useTables(undefined))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.updateStatus('table-123', 'occupied')
        })
      }).rejects.toThrow('Organization ID is required')
    })

    it('should handle database error during status update', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createStatusUpdateQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createStatusUpdateQueryBuilder() {
        const queryBuilder = {
          update: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      const { result } = renderHook(() => useTables(mockOrganizationId))

      // Assert
      await expect(async () => {
        await act(async () => {
          await result.current.updateStatus('table-123', 'occupied')
        })
      }).rejects.toThrow()
    })
  })
})
